package fraymus.workspace;
import org.json.*;import org.junit.Test;import static org.junit.Assert.*;import java.util.*;
public class UsefulObservation072Test {
 static JSONObject model(double x,double v){
  var fit=new JSONArray();var cal=new JSONArray();var df=new JSONArray();var dc=new JSONArray();
  for(String cell:Uncertainty071.CELLS)for(int partition=0;partition<2;partition++)for(int i=0;i<(partition==0?6:9);i++){
   String id=cell+"-"+partition+"-"+i;var values=new JSONArray();var dx=new JSONArray();
   for(int k=0;k<4;k++){values.put(x).put(v);dx.put(x);}
   var a=new JSONObject().put("cell",cell).put("recordId",id).put("recordSha256","fixture-"+id).put("residuals",values);var b=WorldFrames.copy(a);b.remove("residuals");b.put("residualsM",dx);
   (partition==0?fit:cal).put(a);(partition==0?df:dc).put(b);
  }
  return new JSONObject().put("state",StateUncertainty072.fitLabels(fit,cal)).put("distance",Uncertainty071.fitLabels(df,dc));
 }
 static JSONObject task(){return new JSONObject().put("angleDeg",20).put("frictionRatio",1).put("centerM",.15).put("halfWidthM",.012);}
 static JSONObject decision(){return new JSONObject().put("recover",false).put("speedMps",.2).put("execute",true).put("adaptive",true).put("later",true).put("method","useful");}
 @Test public void stateCalibrationPreservesSeparateComponentsAndSources(){var m=model(.01,.03);StateUncertainty072.verify(m);var f=StateUncertainty072.forecast(task(),decision(),null,m);for(Object raw:f.getJSONArray("bands")){var b=(JSONObject)raw;assertEquals(.01,b.getJSONObject("distance").getDouble("residualCenter"),1e-12);assertEquals(.03,b.getJSONObject("speed").getDouble("residualCenter"),1e-12);}m.getJSONObject("state").getJSONObject("cells").getJSONObject("slowing-predicted").put("multiplier",2);m.getJSONObject("state").remove("sha256");m.getJSONObject("state").put("sha256",WorldFrames.hash(m.getJSONObject("state")));assertThrows(IllegalStateException.class,()->StateUncertainty072.verify(m));}
 @Test public void riskyButUnreachableDoesNotBuyAReading(){var t=task().put("centerM",2);var m=model(0,0);assertEquals(92,Uncertainty071.schedule(t,decision(),null,m.getJSONObject("distance")).getInt("selectedTick"));for(boolean simple:List.of(false,true)){var p=ObservationValue072.plan(t,decision(),null,m,simple);assertEquals(-1,p.getInt("selectedTick"));}var p=ObservationValue072.plan(t,decision(),null,m,false);for(Object raw:p.getJSONArray("candidates")){var c=(JSONObject)raw;assertEquals(0,c.getDouble("weightedActions"),0);assertEquals(0,c.getDouble("savedFraction"),0);assertEquals(1,c.getDouble("unreachableFraction"),1e-12);}}
 @Test public void alreadySafeStateSkipsAndUsefulCandidatesPayTheirCosts(){var m=model(0,0);var safe=ObservationValue072.plan(task().put("halfWidthM",1),decision(),null,m,false);assertEquals(-1,safe.getInt("selectedTick"));var p=ObservationValue072.plan(task(),decision(),null,m,false);assertTrue(p.toString(),p.getInt("selectedTick")>0);for(Object raw:p.getJSONArray("candidates")){var c=(JSONObject)raw;assertEquals(c.getDouble("checkedUtility")-c.getDouble("noCheckUtility"),c.getDouble("gain"),1e-12);assertEquals(81,c.getInt("hypotheticalStates"));assertEquals(9,c.getJSONArray("scenarios").length());assertTrue(c.getDouble("weightedActions")>=0&&c.getDouble("weightedActions")<=1+1e-12);}assertEquals(.01,p.getDouble("scheduleFee"),0);}
 @Test public void degenerateStateGridMatchesOriginalScenarioValue(){var t=task();var d=decision();var old=ObservationSchedule070.plan(t,d,null);var p=ObservationValue072.plan(t,d,null,model(0,0),false);assertEquals(old.getInt("selectedTick"),p.getInt("selectedTick"));for(int i=0;i<3;i++){var a=old.getJSONArray("candidates").getJSONObject(i);var b=p.getJSONArray("candidates").getJSONObject(i);assertEquals(a.getDouble("gain"),b.getDouble("gain"),1e-12);assertEquals(a.getDouble("weightedActions"),b.getDouble("weightedActions"),1e-12);}}
 @Test public void noUnpaidFirstObservationOrFutureInput(){assertThrows(IllegalArgumentException.class,()->ObservationValue072.plan(task(),decision(),new JSONObject(),model(0,0),false));var t=task();var a=ObservationValue072.plan(t,decision(),null,model(0,0),false);t.put("futureActualEvent",new JSONObject().put("tick",84).put("impulse",1000));assertTrue(a.similar(ObservationValue072.plan(t,decision(),null,model(0,0),false)));}
 @Test public void freshPartitionsAndFivePoliciesKeepOriginalFirstActions(){var seen=new HashSet<String>();for(String phase:List.of("fit","calibration","clean","disturbed","unsupported")){var old=Set.of("fit","calibration").contains(phase)?UncertainStudy071.training(phase):UncertainStudy071.cases(phase);for(Object raw:old)seen.add(WorldFrames.hash(((JSONObject)raw).getJSONObject("task")));}var current=new HashSet<String>();for(String phase:List.of("fit","calibration","clean","disturbed","unsupported")){var rows=Set.of("fit","calibration").contains(phase)?UsefulStudy072.training(phase):UsefulStudy072.cases(phase);for(Object raw:rows){var t=((JSONObject)raw).getJSONObject("task");String key=WorldFrames.hash(t);assertFalse(seen.contains(key));assertTrue(current.add(key));var plan=UsefulPolicy072.initial(t);for(String m:List.of("blind","adaptive","uncertain"))assertTrue(plan.getJSONObject("decisions").getJSONObject(m).similar(UncertainPolicy071.initial(t).getJSONObject("decisions").getJSONObject(m)));}}assertEquals(180,current.size());assertEquals(666,UsefulStudy072.TOTAL);assertEquals(6,UsefulStudy072.parityCases().length());}
 @Test public void qualificationChecksSimpleAndOldPoliciesWithoutChangingGate(){var methods=new JSONObject();var pairs=new JSONObject();for(String m:UsefulPolicy072.METHODS){methods.put(m,new JSONObject().put("successes",40));if(!m.equals("useful"))pairs.put(m,new JSONObject().put("meanDelta",.01));}var e=new JSONObject().put("methods",methods).put("pairedUsefulMinus",pairs).put("coverage",new JSONObject().put("jointCoverage",.9));assertTrue(UsefulStudy072.qualifies(e,"clean"));pairs.getJSONObject("simple").put("meanDelta",-.001);assertFalse(UsefulStudy072.qualifies(e,"clean"));assertTrue(UsefulStudy072.qualifies(e,"disturbed"));pairs.getJSONObject("simple").put("meanDelta",-.031);assertFalse(UsefulStudy072.qualifies(e,"disturbed"));}
 @Test public void reportRoutingRetainsJavaOwnership(){assertEquals("agent",ChatPolicy044.route("Inspect useful observation and remaining correction ability",new JSONObject(),false));assertEquals("workbench",ChatPolicy044.route("Build a website about observation value",new JSONObject(),false));}
}
